import{j as e}from"./blog-pages-Br50gGHk.js";import{P as n}from"./compare-pages-DdHzJJD8.js";const a=[{factor:"Asset scope",atlantis:"Subsea trees, manifolds, jumpers, flowlines, risers, umbilicals, structures",competitor:"—"},{factor:"Primary failure modes",atlantis:"External corrosion, CP system performance, fatigue, free-span vibration, scour, cathodic disbondment, internal corrosion in dead-leg sections",competitor:"—"},{factor:"Inspection methods",atlantis:"ROV visual + general visual + close visual + CP probe + thickness UT + flooded-member detection + multi-beam survey",competitor:"—"},{factor:"Code references",atlantis:"API 17B (flexibles), API 17J/K (umbilicals), DNV-OS-F101 (pipelines), DNV-RP-F101 (corroded pipelines), NACE SP0102",competitor:"—"},{factor:"Inspection cycle",atlantis:"Annual ROV survey typical; class society / regulator alignment per asset class",competitor:"—"},{factor:"Atlantis ROI typical",atlantis:"$1M–$4M/yr per field — defensible inspection program + integrity-led intervention planning + reduced ROV time",competitor:"—"},{factor:"Implementation",atlantis:"12–16 weeks for first field live",competitor:"—"}],t=[{question:"How does Atlantis handle ROV inspection data?",answer:"ROV inspection data — video archive, still imagery, CP probe readings, UT thickness measurements, multi-beam survey results — imports natively as structured per-asset records. Major ROV survey vendor data formats supported. The 3D field model overlays inspection state per asset (last inspected date, finding severity, CP performance, scour depth). ROV video links to the inspection record for post-survey review and dispute resolution."},{question:"What about flowline and SCR fatigue?",answer:"Flowlines and Steel Catenary Risers are tracked with fatigue accumulation models driven by metocean data (wave height, current, vessel motion if floating production). VIV (Vortex-Induced Vibration) susceptibility tracks for free-span sections per DNV-RP-F105. Touchdown zone fatigue for SCRs gets specific tracking — it&rsquo;s typically the highest-fatigue section. Inspection scheduling responds to fatigue accumulation rather than just calendar."},{question:"Cathodic protection on subsea?",answer:"Subsea CP system performance — anode wastage, structure-to-electrolyte potentials, ICCP system output where applicable — is logged on every inspection. Anode life remaining is calculated from initial anode mass and observed wastage rate. Atlantis flags anode depletion well in advance of failure so anode retrofit campaigns can be planned. Cathodic disbondment of FBE / 3LPP coatings tracks alongside CP."},{question:"Free-span monitoring?",answer:"Pipeline free-spans (where pipe is unsupported between seabed contact points) are inspection-by-survey — multi-beam echo sounder bathymetry compared between surveys identifies new spans, growing spans, and changing seabed conditions. Atlantis tracks span length, free-span height, calculated VIV severity per DNV-RP-F105, and trends across surveys. Span rectification work (rock dump, mattress placement, span correction) tracks as integrity events."},{question:"Subsea umbilical and flexible riser integrity?",answer:"Umbilicals and flexibles have specific failure modes — armor wire fatigue, hydrogen embrittlement, end-fitting integrity, polymer aging — that require specific tracking. Atlantis ships templates per API 17B / 17J / 17K with tube-specific records (electrical tubes, hydraulic tubes, steel armor wires). End-fitting inspection events (typically a major intervention requiring specialist contractors) flow into the umbilical record."}];function l(){const s={"@context":"https://schema.org","@graph":[{"@type":"Article",headline:"Atlantis Digital Twin for Subsea: Trees, Manifolds, Flowlines, Risers, Umbilicals [2026]",datePublished:"2026-05-09",dateModified:"2026-05-09",author:{"@type":"Person",name:"Anoop Rayavarapu"},publisher:{"@type":"Organization",name:"Atlantis NDT"},mainEntityOfPage:{"@type":"WebPage","@id":"https://atlantisndt.com/digital-twins/subsea"}},{"@type":"FAQPage",mainEntity:t.map(i=>({"@type":"Question",name:i.question,acceptedAnswer:{"@type":"Answer",text:i.answer}}))}]};return e.jsx(n,{title:"Atlantis Digital Twin for Subsea: Trees, Flowlines, Risers, Umbilicals [2026]",description:"Subsea digital twin: ROV inspection data import, flowline/SCR fatigue, CP performance, free-span monitoring, umbilical & flexible riser integrity per API 17B/17J/17K. $1M-$4M/yr ROI per field.",canonical:"https://atlantisndt.com/digital-twins/subsea",eyebrow:"Use Case",h1:"Atlantis Digital Twin for Subsea: Trees, Flowlines, Risers, Umbilicals [2026]",intro:"Subsea integrity combines ROV survey data, fatigue accumulation models, CP performance, free-span monitoring, and umbilical / flexible riser tracking — all on assets you can’t see and rarely touch. Atlantis Digital Twin manages the full subsea integrity workflow per API 17B / 17J / 17K and DNV standards.",heroGradient:"from-blue-800 to-cyan-900",competitorLabel:"Subsea Specifics",compareRows:a,faqs:t,related:[{href:"/digital-twins/fpso",title:"FPSO",blurb:"Topside complement to subsea field — full field-level twin."},{href:"/digital-twins/offshore-platform",title:"Offshore Platform",blurb:"Fixed platform alternative — different access constraints."},{href:"/digital-twins/pipeline",title:"Pipeline",blurb:"Onshore pipeline equivalent for the linear-asset workflow."},{href:"/digital-twins",title:"Atlantis Digital Twin",blurb:"Product page — features, pricing, case studies."},{href:"/integrations/sap-pm",title:"SAP PM Integration",blurb:"How Atlantis fits with subsea operator SAP / Oracle landscape."},{href:"/contact",title:"Book a Subsea Demo",blurb:"Bring a field layout and a recent ROV survey. We&rsquo;ll show your field as a twin in 30 minutes."}],ctaTitle:"See Your Subsea Field as a Live Integrity Twin",ctaSubtitle:"Trees + manifolds + flowlines + risers + umbilicals in one record. Bring an ROV survey, leave with a working twin demo.",structuredData:s,bodyChildren:e.jsxs(e.Fragment,{children:[e.jsx("h2",{children:"Subsea integrity is data-poor, consequence-rich"}),e.jsx("p",{children:"Subsea integrity is uniquely hard. The assets are out of sight, inspection is expensive (vessel time + ROV operations), inspection cadence is annual at best, and failure consequence is high (release events, lost production, intervention costs that dwarf the original asset value). The integrity engineer’s job is to make the most of every annual ROV survey, prioritize the limited intervention budget effectively, and maintain a defensible engineering record across the field’s life. Atlantis Digital Twin organizes the subsea integrity workflow in one platform with a 3D field overlay showing live integrity state per asset."}),e.jsx("h2",{children:"Asset class coverage"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Subsea trees and chokes."})," Periodic inspection records, valve operability checks, choke wear tracking, methanol injection performance."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Manifolds and PLEM/PLET."})," Connection integrity, jumper interface, hub seal performance."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Jumpers (rigid and flexible)."})," Inspection per jumper with end-fitting / hub interface tracking."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Flowlines."})," CIPS / coupon / UT inspection where access permits, ROV visual, free-span survey, integrity calculation per DNV-RP-F101."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Risers — SCR / TTR / Flexibles."})," Fatigue tracking, touchdown zone monitoring (SCRs), end-fitting inspection (flexibles per API 17B)."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Umbilicals."})," Tube-by-tube tracking per API 17J / 17K — electrical tubes, hydraulic tubes, steel armor wires, end-fitting integrity."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Subsea structures."})," Templates, foundations, mudline interface, scour protection."]})]}),e.jsx("h2",{children:"ROV inspection data flow"}),e.jsx("p",{children:"ROV survey data imports natively as structured per-asset records — video archive, still imagery, CP probe readings, UT thickness measurements (where access permits), multi-beam survey results, scour depth measurements. Major ROV survey vendor data formats supported. The 3D field model overlays inspection state per asset (last inspected date, finding severity, CP performance, scour depth). Inspector or integrity engineer can replay the ROV video directly from the asset record for post-survey review or dispute resolution."}),e.jsx("h2",{children:"Fatigue accumulation"}),e.jsx("p",{children:"Flowlines and risers accumulate fatigue from environmental loads (wave, current, vortex-induced vibration on free-spans) and operational loads (pressure cycling, thermal cycling). Atlantis tracks fatigue accumulation per asset using metocean data feeds where available and operating data where relevant. Touchdown zone fatigue for SCRs gets specific tracking — it’s typically the highest-fatigue section. VIV susceptibility per DNV-RP-F105 calculated for free-span sections."}),e.jsx("h2",{children:"Cathodic protection management"}),e.jsx("p",{children:"Subsea CP performance — anode wastage, structure-to-electrolyte potentials, ICCP output — logs on every inspection survey. Anode life remaining is calculated from initial anode mass and observed wastage rate. Atlantis flags anode depletion well in advance of failure so anode retrofit campaigns can be planned ahead of vessel availability. Cathodic disbondment of FBE / 3LPP coatings tracks alongside CP."}),e.jsx("h2",{children:"Free-span monitoring"}),e.jsx("p",{children:"Pipeline free-spans are inspection-by-survey — multi-beam echo sounder bathymetry compared between surveys identifies new spans, growing spans, and changing seabed. Atlantis tracks span length, free-span height, calculated VIV severity per DNV-RP-F105, and trends across surveys. Span rectification work (rock dump, mattress placement, span correction) tracks as integrity events with cost and effectiveness recorded."}),e.jsx("h2",{children:"Umbilical and flexible riser integrity"}),e.jsx("p",{children:"Umbilicals and flexibles have specific failure modes — armor wire fatigue, hydrogen embrittlement, end-fitting integrity, polymer aging. Atlantis ships templates per API 17B / 17J / 17K with tube-specific records and end-fitting inspection event tracking. End-fitting inspection is a major intervention requiring specialist contractors — the structured record supports defensible scope definition and contractor handover."})]})})}export{l as default};
